```openscad
// Round-bottom flask support ring with three legs
// Print orientation: legs stand on the bed (z = 0), ring on top (top face at z = 50)

$fn = 96;

// ---- Ring ----
ring_od        = 70;   // ring outer diameter
ring_id        = 54;   // ring inner diameter (flask seat opening)
ring_thick     = 4;    // ring thickness (Z)
ring_top_z     = 50;   // height of ring top face above bed

// ---- Legs ----
leg_d          = 6;    // leg diameter
leg_circle_d   = 62;   // diameter of circle through leg axes
leg_count      = 3;    // number of legs
leg_start_ang  = 0;    // first leg on +X axis

// ---- Derived ----
ring_bot_z     = ring_top_z - ring_thick;   // ring underside height
overlap        = 0.5;                        // leg overlap into ring for clean union
eps            = 0.5;                        // cutter overshoot

union() {
    // Flat annular ring
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_thick);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_thick + 2 * eps);
        }

    // Three legs from bed up into the ring
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bot_z + overlap, $fn = 64);
    }
}
```

