```openscad
// Round-bottom flask support ring with three legs
// Units: mm. Prints as modelled: legs stand on the bed at z = 0.

$fn = 96;

// ---- Ring ----
ring_od        = 70;   // outer diameter of the flat ring
ring_id        = 50;   // inner diameter of the flat ring
ring_thick     = 5;    // ring thickness (Z)
ring_top_z     = 60;   // height of the ring's top face

// ---- Legs ----
leg_d          = 6;    // leg diameter
leg_circle_d   = 60;   // diameter of the circle the leg axes lie on
leg_count      = 3;    // number of legs
leg_start_ang  = 0;    // first leg on the +X axis (degrees)
leg_overlap    = 1;    // how far legs extend into the ring so they fuse with it

// ---- Clearance for clean booleans ----
eps            = 0.5;  // extension of cutting shapes past the faces they cut

// Derived values
ring_bot_z = ring_top_z - ring_thick;   // underside of the ring (z = 55)

module ring() {
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_thick);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_thick + 2 * eps);
        }
}

module legs() {
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bot_z + leg_overlap);
    }
}

union() {
    ring();
    legs();
}
```

