// Spacer with counterbore for a socket-head screw
// Print orientation: standing on bed, z = 0 to 15, centred on origin

$fn = 96;               // facet count for round features

body_d      = 20;       // outer diameter of spacer (mm)
body_h      = 15;       // overall height of spacer (mm)
hole_d      = 5.5;      // through-hole diameter (mm)
cbore_d     = 10;       // counterbore diameter (mm)
cbore_depth = 5;        // counterbore depth from top face (mm)
eps         = 0.5;      // overshoot for clean boolean cuts (mm)

difference() {
    // Main cylindrical body
    cylinder(d = body_d, h = body_h);

    // Through-hole along the axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = body_h + 2 * eps);

    // Counterbore from the top face (z = 10 to z = 15)
    translate([0, 0, body_h - cbore_depth])
        cylinder(d = cbore_d, h = cbore_depth + eps);
}
