```openscad
// Sliding mount: base plate with a dovetail rail along X
// Print orientation: plate flat on bed, rail on top

$fn = 64;

// ---- Base plate ----
plate_len   = 60;   // X length of base plate
plate_wid   = 40;   // Y width of base plate
plate_thk   = 6;    // Z thickness of base plate (z = 0..6)

// ---- Dovetail rail ----
rail_len    = plate_len; // rail runs full plate length
rail_w_bot  = 10;   // rail width where it meets the plate (z = 6)
rail_w_top  = 14;   // rail width at its top face (z = 12)
rail_top_z  = 12;   // Z of rail top face
overlap     = 0.01; // small embed of rail into plate for a clean union

rail_h = rail_top_z - plate_thk; // rail height above plate

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    // 2D profile: x -> world Y, y -> world Z; extruded along world X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_w_bot/2, plate_thk - overlap],
                [ rail_w_bot/2, plate_thk - overlap],
                [ rail_w_top/2, rail_top_z],
                [-rail_w_top/2, rail_top_z]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
```

```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate flat on bed, rail pointing up (+Z)

$fn = 64;

// ---------------- Base plate ----------------
plate_len   = 60;   // X length of base plate
plate_wid   = 40;   // Y width of base plate
plate_thk   = 4;    // Z thickness of base plate (z = 0..4)

// ---------------- Dovetail rail ----------------
rail_len    = plate_len; // rail runs full length of plate
rail_w_bot  = 10;   // rail width where it meets plate (z = plate_thk)
rail_w_top  = 16;   // rail width at top face
rail_top_z  = 9;    // Z height of rail top face

// ---------------- Misc ----------------
overlap     = 0.01; // small overlap so rail fuses into plate

// Rail cross-section in YZ (polygon X -> world Y, polygon Y -> world Z)
module rail_profile() {
    polygon(points = [
        [-rail_w_bot/2, plate_thk - overlap],   // bottom left (sunk slightly into plate)
        [ rail_w_bot/2, plate_thk - overlap],   // bottom right
        [ rail_w_bot/2, plate_thk],             // meets plate
        [ rail_w_top/2, rail_top_z],            // top right (flared)
        [-rail_w_top/2, rail_top_z],            // top left (flared)
        [-rail_w_bot/2, plate_thk]              // meets plate
    ]);
}

module dovetail_rail() {
    // Extrude along X, centred on origin
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            rail_profile();
}

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

union() {
    base_plate();
    dovetail_rail();
}
```

