// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

$fn = 64;

// ---------------- Base plate ----------------
plate_len   = 60;   // plate length along X (mm)
plate_wid   = 36;   // plate width along Y (mm)
plate_thk   = 4;    // plate thickness along Z (mm), z = 0..4

// ---------------- Dovetail rail ----------------
rail_bot_w  = 14;   // rail width where it meets the plate, at z = plate_thk (mm)
rail_top_w  = 18;   // rail width at its top face (mm)
rail_top_z  = 9;    // absolute Z of the rail top face (mm)
rail_len    = plate_len;  // rail runs the full plate length (mm)
overlap     = 0.01; // small overlap into plate so the union fuses cleanly (mm)

rail_h = rail_top_z - plate_thk;  // rail height above plate (mm)

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    // Trapezoid drawn in the YZ plane, extruded along X.
    // rotate([90,0,90]) maps polygon x -> Y, polygon y -> Z, extrusion -> X
    translate([0, 0, plate_thk])
        rotate([90, 0, 90])
            linear_extrude(height = rail_len, center = true)
                polygon(points = [
                    [-rail_bot_w/2, -overlap],
                    [ rail_bot_w/2, -overlap],
                    [ rail_top_w/2,  rail_h],
                    [-rail_top_w/2,  rail_h]
                ]);
}

union() {
    base_plate();
    dovetail_rail();
}
