```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

$fn = 64;

// ---------------- Dimensions (mm) ----------------
plate_len      = 80;   // base plate length along X
plate_wid      = 30;   // base plate width along Y
plate_thk      = 6;    // base plate thickness (z = 0 to 6)

rail_len       = plate_len; // rail runs the full plate length
rail_bot_wid   = 12;   // dovetail width where it meets the plate (z = 6)
rail_top_wid   = 18;   // dovetail width at its top face (z = 14)
rail_top_z     = 14;   // z height of the rail's top face
rail_hgt       = rail_top_z - plate_thk; // rail height (8 mm)

overlap        = 0.01; // small overlap so rail fuses with plate

// Half-width of the flank at the slightly lowered overlap height
flare_per_mm   = (rail_top_wid - rail_bot_wid) / 2 / rail_hgt; // outward flare per mm of height
ov_half_wid    = rail_bot_wid / 2 - flare_per_mm * overlap;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, sitting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    // rotate([90,0,90]) maps 2D x -> Y, 2D y -> Z, extrusion -> X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-ov_half_wid,       plate_thk - overlap], // bottom left
                [ ov_half_wid,       plate_thk - overlap], // bottom right
                [ rail_top_wid / 2,  rail_top_z],          // top right
                [-rail_top_wid / 2,  rail_top_z]           // top left
            ]);
}
