// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 100;   // base plate length (X)
plate_wid   = 40;    // base plate width (Y)
plate_t     = 4;     // base plate thickness (Z), z = 0..4

rail_w_bot  = 14;    // dovetail width where it meets the plate (z = 4)
rail_w_top  = 18;    // dovetail width at its top face (z = 10)
rail_top_z  = 10;    // absolute Z of rail top face
rail_h      = rail_top_z - plate_t;  // rail height (6 mm)

eps         = 0.01;  // small overlap so rail fuses into plate (no coplanar faces)

$fn = 64;

// Rail half-width at a given height above the plate top (linear flare)
function rail_half_w(dz) = (rail_w_bot + (rail_w_top - rail_w_bot) * dz / rail_h) / 2;

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Dovetail rail: trapezoid in YZ, extruded along full X length.
    // rotate([90,0,90]) maps 2D x -> Y, 2D y -> Z, extrusion -> X
    rotate([90, 0, 90])
        linear_extrude(height = plate_len, center = true)
            polygon(points = [
                [-rail_half_w(-eps), plate_t - eps],  // bottom-left (slightly inside plate)
                [ rail_half_w(-eps), plate_t - eps],  // bottom-right
                [ rail_w_top/2,      rail_top_z],     // top-right
                [-rail_w_top/2,      rail_top_z]      // top-left
            ]);
}
