// Glass stirring rod rest - rectangular block with 3 V-grooves across the top

// ---------- Block dimensions ----------
block_len   = 50;   // length along X (mm)
block_wid   = 30;   // width along Y (mm)
block_ht    = 15;   // height along Z (mm)

// ---------- Groove dimensions ----------
