module v_groove() {
    hw = groove_top_w / 2;
    // V profile in X-Z, extended above the top face along the same 45-degree flanks
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * eps, center = true)
            polygon(points = [
                [-(hw + eps), eps],
                [ (hw + eps), eps],
                [0, -groove_depth]
            ]);
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves, centred along X
    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, block_ht])
            v_groove();
