// Glass stirring rod rest - block with 3 V-grooves across the top
// Print orientation: flat on bed, grooves facing up

$fn = 64;

// ---- Block dimensions ----
block_len   = 60;   // X length (mm)
block_wid   = 40;   // Y width (mm)
block_h     = 12;   // Z height (mm)

// ---- Groove dimensions ----
groove_count   = 3;    // number of V-grooves
groove_pitch   = 20;   // centre-to-centre spacing along X (mm)
groove_top_w   = 8;    // V width at top surface (mm)
groove_depth   = 4;    // V depth (mm) -> 90 deg included angle
cut_overshoot  = 1;    // extension of cutters past faces (mm)

// Derived: half-width of the cutter at its top, extended above the surface
// while keeping the 45-degree flanks (90-degree V)
groove_half_top = groove_top_w / 2 + cut_overshoot * (groove_top_w / 2) / groove_depth;

module v_groove_cutter() {
    // Triangle in the X-Z plane, extruded along Y
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * cut_overshoot, center = true)
            polygon(points = [
                [-groove_half_top, cut_overshoot],
                [ groove_half_top, cut_overshoot],
                [ 0,              -groove_depth]
            ]);
}

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves centred along X
    for (i = [0 : groove_count - 1]) {
        x = (i - (groove_count - 1) / 2) * groove_pitch;
        translate([x, 0, block_h])
            v_groove_cutter();
    }
}
