// Print orientation: flat on the bed, grooves facing up

// ---------------- Parameters ----------------
block_l      = 105;   // block length along X (mm)
block_w      = 50;    // block width along Y (mm)
block_h      = 18;    // block height along Z (mm)

groove_count = 6;     // number of V-grooves
groove_pitch = 15;    // centre-to-centre groove spacing along X (mm)
groove_top_w = 8;     // groove width at the top surface (mm)
groove_depth = 4;     // groove depth (mm); 8 wide x 4 deep gives a 90-degree V

overcut      = 1;     // extra cutter extension past the faces it cuts (mm)

$fn = 64;

// ---------------- Derived ----------------
half_top  = groove_top_w / 2;               // half-width at the top surface
// Keep the same V angle when the cutter extends above the top face
half_over = half_top + overcut * (half_top / groove_depth);
first_x   = -(groove_count - 1) * groove_pitch / 2;   // centre the grooves in X

// ---------------- Groove cutter ----------------
// V profile in the XZ plane, extruded along Y through the full width
module v_groove() {
    rotate([90, 0, 0])
        linear_extrude(height = block_w + 2 * overcut, center = true)
            polygon(points = [
                [0,          block_h - groove_depth],  // bottom of the V
                [ half_over, block_h + overcut],       // top right (above top face)
                [-half_over, block_h + overcut]        // top left (above top face)
            ]);
}

// ---------------- Part ----------------
difference() {
    translate([-block_l / 2, -block_w / 2, 0])
        cube([block_l, block_w, block_h]);

    for (i = [0 : groove_count - 1])
        translate([first_x + i * groove_pitch, 0, 0])
            v_groove();
}
```

