    // 90-degree V profile in XZ, extended above top surface along the same 45-degree walls
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * overshoot, center = true)
            polygon(points = [
                [-(groove_top_w / 2 + overshoot), block_h + overshoot],
                [  groove_top_w / 2 + overshoot,  block_h + overshoot],
                [  0,                             block_h - groove_depth]
            ]);
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves, centred as a group along X
    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, 0])
            v_groove();
}
