// Derived
groove_span  = (groove_count - 1) * groove_pitch;   // distance from first to last groove

// One V-groove cutter, centred at x = 0, running along Y, apex at block_ht - groove_depth
module v_groove() {
    // Profile drawn in XY (y = height), extended eps above the top face
    // while keeping the exact 90-degree (1:1) flank slope.
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * eps, center = true)
            polygon(points = [
                [-(groove_top_w / 2 + eps), block_ht + eps],
                [  groove_top_w / 2 + eps,  block_ht + eps],
                [  0,                       block_ht - groove_depth]
            ]);
}

difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Grooves, centred along X
    for (i = [0 : groove_count - 1])
        translate([-groove_span / 2 + i * groove_pitch, 0, 0])
            v_groove();
}
