// Captive hex nut clamping block
// Print orientation: bottom face (with hex pocket) on the bed at z = 0

// ---------- Parameters ----------
block_x       = 30;    // block size in X (mm)
block_y       = 30;    // block size in Y (mm)
block_z       = 15;    // block height in Z (mm)

hole_d        = 3.4;   // through-hole diameter (mm)

hex_flats     = 5.6;   // hex pocket width across flats (mm)
hex_depth     = 2.6;   // hex pocket depth from the bottom face (mm)

eps           = 0.5;   // extra length on cutters so no faces are coplanar (mm)
fn_round      = 64;    // facets for round holes

// Circumradius of the hex from the across-flats size
hex_r = (hex_flats / 2) / cos(30);

// ---------- Model ----------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = block_z + 2 * eps, $fn = fn_round);

    // Hex nut pocket from the bottom face.
    // A 6-sided cylinder has a vertex on +X, so two flats are parallel to X.
    translate([0, 0, -eps])
        cylinder(r = hex_r, h = hex_depth + eps, $fn = 6);
}
