tube_id      = 10;   // bore diameter
tube_h       = 20;   // overall height (z = 0 to 20)
slot_count   = 6;    // number of axial slots
slot_w       = 2;    // slot width
slot_bottom  = 5;    // slots run from top down to this z
eps          = 0.5;  // overcut past cut faces

// Derived
slot_len_z   = tube_h - slot_bottom + eps;  // slot height (extends past top)
slot_radial  = tube_od / 2 + eps;           // slot reaches past outer wall

difference() {
    // Tube body
    cylinder(d = tube_od, h = tube_h);

    // Bore
    translate([0, 0, -eps])
        cylinder(d = tube_id, h = tube_h + 2 * eps);

    // Axial slots, first centred on +X
    for (i = [0 : slot_count - 1])
        rotate([0, 0, i * 360 / slot_count])
            translate([0, -slot_w / 2, slot_bottom])
                cube([slot_radial, slot_w, slot_len_z]);
}
