// Cross-shaped bottle stabiliser
// Flat plus-sign plate, printed lying flat on the bed

// ---------- Parameters ----------
plate_thickness = 5;     // plate thickness (Z)
arm_length      = 70;    // overall length of each bar (X and Y)
arm_width       = 15;    // width of each bar
hole_d          = 5.5;   // diameter of all through-holes
hole_offset     = 27.5;  // distance from origin to arm-end hole centres
cut_extra       = 0.5;   // cutter overshoot past faces
$fn             = 64;    // curve resolution

// ---------- Model ----------
difference() {
    // Plus-sign plate
    union() {
        translate([-arm_length/2, -arm_width/2, 0])
            cube([arm_length, arm_width, plate_thickness]);
        translate([-arm_width/2, -arm_length/2, 0])
            cube([arm_width, arm_length, plate_thickness]);
    }

    // Centre hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thickness + 2*cut_extra);

    // Arm-end holes
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a])
            translate([hole_offset, 0, -cut_extra])
                cylinder(d = hole_d, h = plate_thickness + 2*cut_extra);
}
