// Stepped riser - 3 equal solid steps climbing in +X
// Print orientation: base on the bed (z = 0), steps build upward

// ---------------- Parameters ----------------
num_steps   = 3;    // number of steps
step_length = 10;   // length of each step along X (mm)
step_rise   = 6;    // height increase per step (mm)
riser_depth = 20;   // extrusion depth along Y (mm), y = 0 .. 20

total_length = num_steps * step_length;   // 30 mm
total_height = num_steps * step_rise;     // 18 mm

// ---------------- Profile (XZ plane) ----------------
// Staircase outline: starts at origin, runs along bed to x = 30,
// up to the top step, then steps down toward x = 0.
profile_pts = concat(
    [[0, 0], [total_length, 0]],
    [for (i = [num_steps - 1 : -1 : 0])
        each [[(i + 1) * step_length, (i + 1) * step_rise],
              [ i      * step_length, (i + 1) * step_rise]]]
);

// ---------------- Model ----------------
// The 2D profile is drawn in X (horizontal) and Z (vertical).
// rotate([90,0,0]) maps the extrusion axis onto -Y, so translate
// by riser_depth to place the solid at y = 0 .. 20.
translate([0, riser_depth, 0])
    rotate([90, 0, 0])
        linear_extrude(height = riser_depth)
            polygon(points = profile_pts);
