// Stepped riser - solid staircase of 3 equal steps
// Print orientation: resting on the bed (z = 0), building upward (+Z).
// Placed at the user's coordinates: X 0..36, Y 0..20 (not centred).

// ---------------- Parameters ----------------
num_steps   = 3;    // number of steps
step_len    = 12;   // length of each step along X (mm)
step_rise   = 10;   // height increase per step (mm); first step is 10 mm tall
depth_y     = 20;   // extrusion depth along Y (mm), y = 0 .. 20
overlap     = 0.01; // tiny overlap between adjacent blocks for a clean union

$fn = 64;           // no curved features here, set per the rules

// ---------------- Model ----------------
// Each step is a solid block from the bed up to its tread height.
// Step i spans x = i*step_len .. (i+1)*step_len, height = (i+1)*step_rise.
union() {
    for (i = [0 : num_steps - 1]) {
        x0 = i * step_len;
        // extend each block slightly into the next one (except the last)
        // so the union has no coincident internal faces
        len_i = step_len + ((i < num_steps - 1) ? overlap : 0);
        translate([x0, 0, 0])
            cube([len_i, depth_y, (i + 1) * step_rise]);
    }
}
