```openscad
// Gas cylinder label tag
// Flat plate with rounded corners and a cable-tie hole

// ---------- Parameters ----------
plate_length   = 50;    // X dimension of plate (mm)
plate_width    = 20;    // Y dimension of plate (mm)
plate_thick    = 2;     // Z thickness of plate (mm)
corner_radius  = 4;     // corner rounding radius seen from above (mm)

hole_diameter  = 5;     // cable-tie hole diameter (mm)
hole_x         = -18;   // hole centre X position (mm)
hole_y         = 0;     // hole centre Y position (mm)

cut_extra      = 0.5;   // extension of cutters beyond faces (mm)
fn_curve       = 96;    // facets for curved shapes

// ---------- Modules ----------
module rounded_plate(l, w, t, r) {
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx * (l / 2 - r), sy * (w / 2 - r), 0])
                cylinder(r = r, h = t, $fn = fn_curve);
    }
}

// ---------- Model ----------
difference() {
    rounded_plate(plate_length, plate_width, plate_thick, corner_radius);

    // Cable-tie hole, extends past top and bottom faces
    translate([hole_x, hole_y, -cut_extra])
        cylinder(d = hole_diameter, h = plate_thick + 2 * cut_extra, $fn = fn_curve);
}
